package com.mannaggia.app

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.drawable.AnimationDrawable
import android.graphics.drawable.BitmapDrawable
import android.graphics.drawable.StateListDrawable
import android.util.LruCache
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

/**
 * Pixel-art saint portraits from assets/avatar/, generated by tools/ritratti/avatar.py.
 *
 * Each saint is `<sha1(name)[:12]>.png` (48x48), the same id as the audio files.
 * Legendary saints (assets/avatar/leggendari.txt) get an animated gold frame
 * (cornice_00..11.png) drawn on top, or their own frame when cornici.txt names one
 * (e.g. the flames of Saint Joan of Arc, fuoco_00..11.png). With the "Colorful" option
 * the other saints get one too, and martyrs the flames, as listed in cornici_colorful.txt.
 */
object Avatars {

    private const val DIR = "avatar"
    private const val FRAME_COUNT = 12
    /** 12 frames x 167 ms: one sparkle loop every 2 seconds. */
    private const val FRAME_MS = 167
    const val GOLD_FRAME = "cornice"

    private val cache = LruCache<String, Bitmap>(300)

    @Volatile
    private var legendary: Set<String>? = null

    /** Frame name -> its animation frames ("cornice" is the gold one). */
    private val frameCache = ConcurrentHashMap<String, List<Bitmap>>()

    /** Saint -> special frame name, from cornici.txt. */
    @Volatile
    private var specialFrames: Map<String, String>? = null

    /** Saint -> frame name with the "Colorful" option, from cornici_colorful.txt. */
    @Volatile
    private var colorfulFrames: Map<String, String>? = null

    /** Saint -> card number (1 = most famous), from catalogo.txt. */
    @Volatile
    private var numbers: Map<String, Int>? = null

    /** Same id as tools/tts/genera_audio.py and tools/ritratti/avatar.py. */
    fun fileId(saint: String): String =
        MessageDigest.getInstance("SHA-1").digest(saint.toByteArray(Charsets.UTF_8))
            .joinToString("") { "%02x".format(it) }.take(12)

    /** The saint's 48x48 portrait, or null if missing. */
    suspend fun load(context: Context, saint: String): Bitmap? = withContext(Dispatchers.IO) {
        cache.get(saint) ?: runCatching { decode(context, "${fileId(saint)}.png") }.getOrNull()
            ?.also { cache.put(saint, it) }
    }

    suspend fun isLegendary(context: Context, saint: String): Boolean = withContext(Dispatchers.IO) {
        val set = legendary ?: runCatching {
            context.applicationContext.assets.open("$DIR/leggendari.txt").bufferedReader(Charsets.UTF_8)
                .useLines { lines -> lines.map { it.trim() }.filter { it.isNotEmpty() && !it.startsWith("#") }.toSet() }
        }.getOrDefault(emptySet()).also { legendary = it }
        saint in set
    }

    /** Card number of [saint]: 1 is the most famous (and rarest to find among the famous). */
    suspend fun number(context: Context, saint: String): Int? = withContext(Dispatchers.IO) {
        val map = numbers ?: runCatching {
            context.applicationContext.assets.open("$DIR/catalogo.txt").bufferedReader(Charsets.UTF_8)
                .useLines { lines ->
                    lines.map { it.trim() }.filter { it.isNotEmpty() && !it.startsWith("#") }
                        .withIndex().associate { (i, s) -> s to i + 1 }
                }
        }.getOrDefault(emptyMap()).also { numbers = it }
        map[saint]
    }

    /** The pixel-art card binder icon of the main screen. */
    suspend fun binder(context: Context): BitmapDrawable? = icon(context, "raccoglitore.png")

    /** The pixel-art trophy cup (main screen, trophy list, unlock banner). */
    suspend fun cup(context: Context): BitmapDrawable? = icon(context, "coppa.png")

    /** Banner bookmark of the favourite cards: [full] for a favourite, a faint outline otherwise. */
    suspend fun bookmark(context: Context, full: Boolean): BitmapDrawable? =
        icon(context, if (full) "segnalibro.png" else "segnalibro_vuoto.png")

    /** Splash screen: the app icon in pixel art (halo and speech bubble) and the title. */
    suspend fun splashLogo(context: Context): Bitmap? = icon(context, "logo.png")?.bitmap
    suspend fun splashTitle(context: Context): Bitmap? = icon(context, "titolo.png")?.bitmap

    /** Still silver frame of the special cards. */
    suspend fun silverFrame(context: Context): BitmapDrawable? = icon(context, "cornice_argento.png")

    /** The "Nuova!" stamp on new cards (red initial, gothic lowercase, on parchment). */
    suspend fun newStamp(context: Context): BitmapDrawable? = icon(context, "timbro_nuova.png")

    /**
     * A pixel-art ribbon button of the main screen ("mannaggia", "opzioni", "info"): gold
     * initial on red, readable on any theme. Darker when pressed, half transparent while
     * disabled (the "Mannaggia!" button during an invocation).
     */
    suspend fun ribbonButton(context: Context, name: String): StateListDrawable? = withContext(Dispatchers.IO) {
        runCatching {
            val normal = decode(context, "pulsante_$name.png")
            val pressed = decode(context, "pulsante_${name}_premuto.png")
            StateListDrawable().apply {
                addState(intArrayOf(-android.R.attr.state_enabled), pixelated(context, normal).apply { alpha = 128 })
                addState(intArrayOf(android.R.attr.state_pressed), pixelated(context, pressed))
                addState(intArrayOf(), pixelated(context, normal))
            }
        }.getOrNull()
    }

    /** The pixel-art saint-of-the-day icon (calendar page with a gold star). */
    suspend fun saintOfDayIcon(context: Context): BitmapDrawable? = icon(context, "santo_del_giorno.png")

    private suspend fun icon(context: Context, file: String): BitmapDrawable? = withContext(Dispatchers.IO) {
        runCatching { pixelated(context, decode(context, file)) }.getOrNull()
    }

    /**
     * Name of the animated frame of [saint], or null for none. With the "Colorful" option,
     * the one in cornici_colorful.txt; otherwise (and for legendary saints not listed there)
     * legendary saints only: their own from cornici.txt, or the one chosen in Options.
     */
    suspend fun frameName(context: Context, saint: String): String? = withContext(Dispatchers.IO) {
        if (Prefs.colorfulEnabled(context)) {
            val colorful = colorfulFrames ?: frameTable(context, "cornici_colorful.txt").also { colorfulFrames = it }
            colorful[saint]?.let { return@withContext it }
        }
        if (!isLegendary(context, saint)) return@withContext null
        val special = specialFrames ?: frameTable(context, "cornici.txt").also { specialFrames = it }
        special[saint] ?: Prefs.frame(context)          // read every time: the choice can change in Options
    }

    /** A saint<TAB>frame table from assets/avatar/[file]. */
    private fun frameTable(context: Context, file: String): Map<String, String> = runCatching {
        context.applicationContext.assets.open("$DIR/$file").bufferedReader(Charsets.UTF_8)
            .useLines { lines ->
                lines.filter { it.isNotBlank() && !it.startsWith("#") }
                    .mapNotNull { line -> line.split('\t').takeIf { it.size == 2 }?.let { it[0].trim() to it[1].trim() } }
                    .toMap()
            }
    }.getOrDefault(emptyMap())

    /**
     * A new animated frame [name] (from [frameName]): the sparkling gold one, or another
     * (each view needs its own drawable; the bitmaps are shared).
     */
    suspend fun frameDrawable(context: Context, name: String): AnimationDrawable = withContext(Dispatchers.IO) {
        val bitmaps = frameBitmaps(context, name)
        AnimationDrawable().apply {
            for (b in bitmaps) addFrame(pixelated(context, b), FRAME_MS)
            isOneShot = false
        }
    }

    /** The frames of animation [name] (<name>_00..11.png); the gold ones if they are missing. */
    private fun frameBitmaps(context: Context, name: String): List<Bitmap> =
        frameCache[name] ?: runCatching {
            (0 until FRAME_COUNT).map { i -> decode(context, "${name}_%02d.png".format(i)) }
        }.getOrElse { if (name == GOLD_FRAME) throw it else return frameBitmaps(context, GOLD_FRAME) }
            .also { frameCache[name] = it }

    /** Scale up without smoothing, so the pixels stay crisp. */
    fun pixelated(context: Context, bitmap: Bitmap) =
        BitmapDrawable(context.resources, bitmap).apply { isFilterBitmap = false }

    private fun decode(context: Context, file: String): Bitmap =
        context.applicationContext.assets.open("$DIR/$file").use { input ->
            BitmapFactory.decodeStream(input, null, BitmapFactory.Options().apply { inScaled = false })
                ?: error("cannot decode $file")
        }
}
